        "place_id":  "ChIJg5qWU7irQjQR2loPcpgDxdE",
        "name":  "30 thirty",
        "address":  "No. 17號, Lane 26, Yixian Rd, 信義區 Xinyi District, Taipei City, Taiwan 110",
        "formatted_address":  "No. 17號, Lane 26, Yixian Rd, 信義區 Xinyi District, Taipei City, Taiwan 110",
        "district":  "信義區",
        "rating":  "4.4",
        "user_ratings_total":  1889,
        "price_level":  "PRICE_LEVEL_MODERATE",
