                            "publishTime":  "2025-11-11T01:33:38.780475021Z",
                            "flagContentUri":  "https://www.google.com/local/content/rap/report?postId=Ci9DQUlRQUNvZENodHljRjlvT2sxUk9YWmZRazEyWlhaVlFsaFdSM0pVVEVKWFNsRRAB\u0026d=17924085\u0026t=1",
                            "googleMapsUri":  "https://www.google.com/maps/reviews/data=!4m6!14m5!1m4!2m3!1sCi9DQUlRQUNvZENodHljRjlvT2sxUk9YWmZRazEyWlhaVlFsaFdSM0pVVEVKWFNsRRAB!2m1!1s0x3442abb4dce16f4d:0xca8d8fe7b51024d4"
